import React, { useCallback, useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomSwitch,
  CustomTimePicker,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";

import usersApi from "../../../api/usersApi";
import employeesApi from "../../../api/employees/employeesApi";
import { Modal } from "antd";
import productsApi from "../../../api/productsApi";
import customerOrdersApi from "../../../api/retailers/customerOrdersApi";

export default function OutOfStockFormModal({
  ismodalOpen,
  setisModalOpen,
  selectedOutOfStock,
  modalTitle = "Add new out of stock item",
  updated,
  setUpdated,
}) {
  console.log("sacco_personnel at modal", selectedOutOfStock);
  console.log("isModalOpen", ismodalOpen);

  const [crew, setCrew] = useState(
    selectedOutOfStock && selectedOutOfStock.crew_array
      ? selectedOutOfStock.crew_array.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      : []
  );

  const employeesActionsApi = useApi(employeesApi.employeesActionAdmin);
  const getEntityEmployees = async () => {
    await employeesActionsApi.request({
      action: "RetrieveEntityEmployees",
    });
  };

  useEffect(() => {
    getEntityEmployees();
  }, []);

  useEffect(() => {
    if (employeesActionsApi.data && employeesActionsApi.data.length) {
      setCrew(
        employeesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("countriesActionsApi.data", employeesActionsApi.data);
  }, [employeesActionsApi.data]);

  const getRoutesActionsApi = useApi(transportApi.transportAction);
  const outOfStockActionsApi = useApi(
    customerOrdersApi.customerOrdersStaffAction
  );
  const getRoutes = async () => {
    await getRoutesActionsApi.request({
      action: "GetEntityRoutes",
    });
  };

  useEffect(() => {
    getRoutes();
  }, []);

  const [errors, setErrors] = useState();

  const handleOutOfStockeAction = async (data) => {
    console.log("data at", data);
    const result = await outOfStockActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      // setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {}, [selectedOutOfStock]);

  useEffect(() => {
    if (outOfStockActionsApi.data) {
      // setisModalOpen(false);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (outOfStockActionsApi.data.errors) {
        setErrors(outOfStockActionsApi.data.errors);
      } else {
        setisModalOpen(false);
        setUpdated(true);
      }
    }

    console.log("transportActionsApi.data", outOfStockActionsApi.data);
  }, [outOfStockActionsApi.data]);

  const saccoSubscritionActionsApi = useApi(transportApi.transportAction);

  const [saccoSubscriptions, setsaccoSubscriptions] = useState([]);
  const getSaccoSubscriptions = useCallback(async () => {
    await saccoSubscritionActionsApi.request({
      action: "GetSaccoSubscriptions",
    });
  }, []);

  useEffect(() => {
    if (
      saccoSubscritionActionsApi.data &&
      saccoSubscritionActionsApi.data.length
    ) {
      setsaccoSubscriptions(
        saccoSubscritionActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    if (
      saccoSubscritionActionsApi.data &&
      saccoSubscritionActionsApi.data.response_message &&
      saccoSubscritionActionsApi.data.response_code === 1
    ) {
      toast.error(saccoSubscritionActionsApi.data.response_message);
    }

    if (
      saccoSubscritionActionsApi.data &&
      saccoSubscritionActionsApi.data.response_message &&
      saccoSubscritionActionsApi.data.response_code === 0
    ) {
      toast.success(saccoSubscritionActionsApi.data.response_message);
    }

    console.log(
      "saccoSubscritionActionsApi.data",
      saccoSubscritionActionsApi.data
    );
  }, [saccoSubscritionActionsApi.data]);

  const getEntityUsersApi = useApi(usersApi.usersAdminAction);

  const [entityUsers, setEntityUsers] = useState([]);
  const getEntityUsers = useCallback(async () => {
    await getEntityUsersApi.request({
      action: "GetAllUsers",
    });
  }, []);

  useEffect(() => {
    if (getEntityUsersApi.data && getEntityUsersApi.data.length) {
      setEntityUsers(
        getEntityUsersApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    if (
      getEntityUsersApi.data &&
      getEntityUsersApi.data.response_message &&
      getEntityUsersApi.data.response_code === 1
    ) {
      toast.error(getEntityUsersApi.data.response_message);
    }

    if (
      getEntityUsersApi.data &&
      getEntityUsersApi.data.response_message &&
      getEntityUsersApi.data.response_code === 0
    ) {
      toast.success(getEntityUsersApi.data.response_message);
    }

    console.log("getFollowersApi.data", getEntityUsersApi.data);
  }, [getEntityUsersApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    getSaccoSubscriptions();
    getEntityUsers();
  }, []);

  const formik = useFormik({
    initialValues: {
      customer: selectedOutOfStock
        ? {
            value: selectedOutOfStock.customer,
            label: `${selectedOutOfStock.customer_name}`,
          }
        : {},
      product: selectedOutOfStock
        ? {
            label: selectedOutOfStock.product_title,
            value: selectedOutOfStock.product,
          }
        : "",
      required_quantity: selectedOutOfStock
        ? selectedOutOfStock.required_quantity
        : "",
      customer_name: selectedOutOfStock ? selectedOutOfStock.customer_name : "",
      customer_phone: selectedOutOfStock
        ? selectedOutOfStock.customer_phone
        : "",

      is_special_order: selectedOutOfStock
        ? selectedOutOfStock.is_special_order
        : "",
    },

    validationSchema: Yup.object({}),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      let crewArr = [];
      if (values.crew && values.crew.length) {
        values.crew.map((x) => {
          crewArr.push(x.value);
        });
      }

      let routesArr = [];
      if (values.crew && values.routes.length) {
        values.routes.map((x) => {
          routesArr.push(x.value);
        });
      }

      let saccoSubscriptionsArr = [];
      if (values.sacco_subscriptions && values.sacco_subscriptions.length) {
        values.sacco_subscriptions.map((x) => {
          saccoSubscriptionsArr.push(x.value);
        });
      }

      if (selectedOutOfStock) {
        handleOutOfStockeAction({
          action: "UpdateOutOfStockItem",
          out_of_stock_item_id: selectedOutOfStock.id,
          product: values.product.value,
          required_quantity: values.required_quantity,
          is_special_order: values.is_special_order,
          customer_name: values.customer_name,
          customer_phone: values.customer_phone,
        });
      } else {
        handleOutOfStockeAction({
          action: "CreateOutOfStockItem",
          product: values.product.value,
          required_quantity: values.required_quantity,
          is_special_order: values.is_special_order,
          customer_name: values.customer_name,
          customer_phone: values.customer_phone,
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    formik.setFieldValue("is_special_order", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");
  };

  //Load products

  const searchProductsApi = useApi(productsApi.productsAction);

  const searchProducts = async (data) => {
    await searchProductsApi.request(data);
  };
  const [products, setProducts] = useState();
  const loadProductsOptions = async (inputText = "", callback) => {
    searchProducts({
      action: "SearchProducts",
      searchQuery: inputText,
    });
    callback(products.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchProductsApi.data) {
      if (searchProductsApi.data.length) {
        setProducts(searchProductsApi.data);
      }
    }
    console.log("searchProductsApi.data", searchProductsApi.data);
  }, [searchProductsApi.data]);

  return (
    <div className="w-full">
      <Modal
        width={540}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        {errors && errors.length ? (
          <div>
            {errors.map((x) => {
              return <p className="text-red-400 font-bold text-medium">{x}</p>;
            })}
          </div>
        ) : (
          <div></div>
        )}

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.product}
            error={formik.errors.product}
          >
            <CustomSelectAsyncSelect
              className="text-start"
              name="product"
              id="product"
              label="Select product item"
              size="large"
              onChange={(value) => formik.setFieldValue("product", value)}
              value={formik.values.product}
              placeholder="Type product name and select"
              loadOptions={loadProductsOptions}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.customer}
            error={formik.errors.customer}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="customer"
              id="customer"
              label="Select customer"
              size="large"
              onChange={(value) => formik.setFieldValue("customer", value)}
              value={formik.values.customer}
              placeholder="Select customer"
              options={entityUsers}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.required_quantity}
            error={formik.errors.required_quantity}
          >
            <CustomInput
              required={true}
              id="required_quantity"
              name="required_quantity"
              onChange={formik.handleChange}
              placeholder="Enter required unit quantity"
              size="large"
              type="number"
              value={formik.values.required_quantity}
              label="Enter required unit quantity"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.customer_name}
            error={formik.errors.customer_name}
          >
            <CustomInput
              required={true}
              id="customer_name"
              name="customer_name"
              onChange={formik.handleChange}
              placeholder="Enter customer phone"
              size="large"
              type="text"
              value={formik.values.customer_name}
              label="Enter customer name"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.customer_phone}
            error={formik.errors.customer_phone}
          >
            <CustomInput
              required={true}
              id="customer_phone"
              name="customer_phone"
              onChange={formik.handleChange}
              placeholder="Enter customer phone"
              size="large"
              type="text"
              value={formik.values.customer_phone}
              label="Enter customer phone"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.is_special_order}
            error={formik.errors.is_special_order}
          >
            <CustomSwitch
              id="is_special_order"
              checked={formik.values.is_special_order === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
              checkedChildren="Not special order"
              unCheckedChildren="Mark special order"
              label="Is this a special order: "
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
