import React, { useEffect, useState } from 'react'
import useWebSocket, { ReadyState } from "react-use-websocket";
import { getAccessToken } from "../../../helpers/authUtils";
import RetailerOutOfStocksTable from "./RetailerOutOfStocksTable";
import { useNavigate } from "react-router-dom";
import { Loading } from "../../../components";
import { ToastContainer } from "react-toastify";
import OutOfStockFormModal from "./OutOfStockFormModal";
import useApi from "../../../hooks/useApi";
import retailerReceiptsApi from "../../../api/retailers/retailerReceiptsApi";
import customerOrdersApi from "../../../api/retailers/customerOrdersApi";

const columns = [
  { name: "Title", uid: "product_title" },
  { name: "Units per pack", uid: "units_per_pack" },
  { name: "Required qty", uid: "required_quantity" },
  { name: "Customer", uid: "customer_name" },
  { name: "Contact", uid: "customer_phone" },
  { name: "Special Order", uid: "is_special_order" },
  { name: "Indented", uid: "retailer_indent" },
  { name: "Created", uid: "created" },
  { name: "Actions", uid: "actions" },
];
export default function RetailerOutOfStocks() {
  const [openRetailerReceiptFormModal, setopenRetailerReceiptFormModal] =
    useState(false);
  const [userToken, setUserToken] = useState();
  const [retailerReceipt, setRetailerReceipt] = useState();
  // const [retailerReceipts, setRetailerReceipts] = useState([])

  const [updated, setUpdated] = useState(false);
  const [itemsToDisplay, setitemsToDisplay] = useState(50);
  const [modalTitle, setmodalTitle] = useState("");
  const navigate = useNavigate();
  const [retailerReceipts, setretailerReceipts] = useState([]);
  const [loading, setloading] = useState(true);

  const [ismodalOpen, setisModalOpen] = useState(false);
  const [selectedOutOfStock, setselectedOutOfStock] = useState();

  const [data, setdata] = useState();

  const retrieveOutOfStockApi = useApi(
    customerOrdersApi.customerOrdersStaffAction
  );
  useEffect(() => {
    setUserToken(getAccessToken());
  }, []);

  const retrieveOutOfStocks = async () => {
    await retrieveOutOfStockApi.request({
      action: "RetrieveOutOfStockItems",
    });
  };

  useEffect(() => {
    retrieveOutOfStocks();
  }, []);
  useEffect(() => {
    if (updated) {
      retrieveOutOfStocks();
    }
  }, [updated]);

  useEffect(() => {
    if (retrieveOutOfStockApi.data && retrieveOutOfStockApi.data.length) {
      setdata(retrieveOutOfStockApi.data);
    }
  }, [retrieveOutOfStockApi.data]);

  // useEffect(() => {
  //   setdata(retailerReceipts);
  //   console.log("reces", retailerReceipts);
  // }, [retailerReceipts]);

  const handleEditAction = (item) => {
    setisModalOpen(true);

    // setUpdated(false)

    setselectedOutOfStock(item);
    setmodalTitle(`Edit ${item.product_title}`);
  };

  const handleAddAction = () => {
    setisModalOpen(true);

    setUpdated(false);

    setmodalTitle("Add new out of stock");
    setselectedOutOfStock(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/retailers/inventory/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/retailers/inventory/delete/${item.id}`);
  };
  const handleFilter = (e) => {
    console.log("filter", e);

    const search_param = e;

    if (search_param && search_param !== "") {
      setdata(
        retailerReceipts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(retailerReceipts);
      console.log("receipts", retailerReceipts);
      // dispatch()
    }
  };

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />
      {ismodalOpen && (
        <OutOfStockFormModal
          ismodalOpen={ismodalOpen}
          setisModalOpen={setisModalOpen}
          selectedOutOfStock={selectedOutOfStock}
          modalTitle={modalTitle}
          setselectedOutOfStock={setselectedOutOfStock}
          updated={updated}
          setUpdated={setUpdated}
        />
      )}

      {data ? (
        <RetailerOutOfStocksTable
          data={data}
          columns={columns}
          editAction={handleEditAction}
          detailsAction={handleDetailsAction}
          deleteAction={handleDeleteAction}
          addAction={handleAddAction}
          handleFilter={handleFilter}
          itemsToDisplay={itemsToDisplay}
          setitemsToDisplay={setitemsToDisplay}
        />
      ) : (
        <Loading loading={loading} />
      )}
    </div>
  );
}
